36	import org.springframework.samples.petclinic.model.Owner;
37	import org.springframework.samples.petclinic.model.Pet;
38	import org.springframework.samples.petclinic.model.Visit;
39	import org.springframework.samples.petclinic.rest.api.OwnersApi;
40	import org.springframework.samples.petclinic.rest.controller.DuplicateHouseholdException;
41	import org.springframework.samples.petclinic.rest.controller.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.controller.InvalidEmailException;
43	import org.springframework.samples.petclinic.rest.controller.RequiredFieldsMissingException;
