46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        normalizeAddress(ownerFieldsDto);
115	        validateRequiredFields(ownerFieldsDto);
116	        normalizeTelephone(ownerFieldsDto);
117	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
118	        rejectDuplicateHousehold(ownerFieldsDto);
119	        normalizeEmail(ownerFieldsDto);
120	        defaultRegistrationDate(ownerFieldsDto);
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        assignCustomerCode(owner);
124	        assignHouseholdId(owner);
125	        assignNamesakeCount(owner);
126	        assignMembershipNumber(owner);
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        normalizeEmail(ownerFieldsDto);
142	        currentOwner.setAddress(ownerFieldsDto.getAddress());
143	        currentOwner.setCity(ownerFieldsDto.getCity());
144	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
145	        currentOwner.setLastName(ownerFieldsDto.getLastName());
146	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
147	        currentOwner.setEmail(ownerFieldsDto.getEmail());
148	        this.clinicService.saveOwner(currentOwner);
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Transactional
154	    @Override
155	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        this.clinicService.deleteOwner(owner);
161	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
186	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
187	        if (currentOwner != null) {
188	            Pet currentPet = this.clinicService.findPetById(petId);
189	            if (currentPet != null) {
190	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
191	                currentPet.setName(petFieldsDto.getName());
192	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
193	                this.clinicService.savePet(currentPet);
194	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	            }
196	        }
197	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
203	        HttpHeaders headers = new HttpHeaders();
204	        Visit visit = visitMapper.toVisit(visitFieldsDto);
205	        Pet pet = new Pet();
206	        pet.setId(petId);
207	        visit.setPet(pet);
208	        this.clinicService.saveVisit(visit);
209	        VisitDto visitDto = visitMapper.toVisitDto(visit);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
211	            .buildAndExpand(visit.getId()).toUri());
212	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
213	    }
214	
215	
216	    /**
217	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
218	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
219	     * Validation already rejects {@code null} values and the pattern-constrained fields
220	     * when blank, but {@code address} and {@code city} have no pattern, so a
221	     * whitespace-only value would otherwise slip through.
222	     *
223	     * @param ownerFieldsDto the submitted owner fields
224	     * @throws RequiredFieldsMissingException if any required field is missing or blank
225	     */
226	    /**
227	     * Common street-type abbreviations expanded during address normalization. Keys are the
228	     * upper-cased abbreviation tokens; values are their canonical expansions.
229	     */
230	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
231	        "ST", "STREET",
232	        "RD", "ROAD",
233	        "AVE", "AVENUE");
234	
235	    /**
236	     * Normalizes the submitted address on create and writes the canonical value back onto the
237	     * request so it is persisted, echoed back, and used for every downstream address comparison
238	     * (household duplicate detection and the household id). The value is trimmed, internal
239	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
240	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
241	     * {@code null} address is left untouched so the required-field check can report it as missing.
242	     *
243	     * @param ownerFieldsDto the submitted owner fields
244	     */
245	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
246	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
247	    }
248	
249	    /**
250	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
251	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
252	     * expanded to its full form. A {@code null} value is returned unchanged.
253	     *
254	     * @param raw the address to canonicalize, possibly {@code null}
255	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
256	     */
257	    private static String normalizeAddress(String raw) {
258	        if (raw == null) {
259	            return null;
260	        }
261	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
262	        if (collapsed.isEmpty()) {
263	            return collapsed;
264	        }
265	        String[] tokens = collapsed.split(" ");
266	        StringBuilder sb = new StringBuilder(collapsed.length());
267	        for (int i = 0; i < tokens.length; i++) {
268	            if (i > 0) {
269	                sb.append(' ');
270	            }
271	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
272	        }
273	        return sb.toString();
274	    }
275	
276	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
277	        List<String> errors = new ArrayList<>();
278	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
279	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
280	        requireText("address", ownerFieldsDto.getAddress(), errors);
281	        requireText("city", ownerFieldsDto.getCity(), errors);
282	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
283	        if (!errors.isEmpty()) {
284	            throw new RequiredFieldsMissingException(errors);
285	        }
286	    }
287	
288	    private static void requireText(String field, String value, List<String> errors) {
289	        if (value == null || value.isBlank()) {
290	            errors.add(field);
291	        }
292	    }
293	
294	    /**
295	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
296	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
297	     * and echoed back in that form.
298	     *
299	     * @param ownerFieldsDto the submitted owner fields
300	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
301	     *                                        valid E.164 number
302	     */
303	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
304	        String e164 = toE164(ownerFieldsDto.getTelephone());
305	        if (e164 == null) {
306	            throw new RequiredFieldsMissingException(List.of("telephone"));
307	        }
308	        ownerFieldsDto.setTelephone(e164);
309	    }
310	
311	    /**
312	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
313	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
314	     * and country code are present they are kept; otherwise country code {@code '+61'} is
315	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
316	     * must contain 8 to 15 digits after the {@code '+'}.
317	     *
318	     * @param raw the submitted telephone, possibly {@code null}
319	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
320	     */
321	    private static String toE164(String raw) {
322	        if (raw == null) {
323	            return null;
324	        }
325	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
326	        String digits;
327	        if (cleaned.startsWith("+")) {
328	            digits = cleaned.substring(1);
329	        } else {
330	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
331	            digits = "61" + national;
332	        }
333	        if (!digits.matches("[0-9]{8,15}")) {
334	            return null;
335	        }
336	        return "+" + digits;
337	    }
338	
339	    /**
340	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
341	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
342	     * each stored owner's telephone is normalized the same way before comparison so differing
343	     * input formats collapse to the same value.
344	     *
345	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
346	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
347	     *                                     same E.164 telephone
348	     */
349	    /**
350	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
351	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
352	     * the parts may contain whitespace or a second {@code @}.
353	     */
354	    private static final Pattern EMAIL_PATTERN =
355	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
356	
357	    /**
358	     * Normalizes the submitted email when present: the value is trimmed, required to be a
359	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
360	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
361	     *
362	     * @param ownerFieldsDto the submitted owner fields
363	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
364	     */
365	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
366	        String email = ownerFieldsDto.getEmail();
367	        if (email == null) {
368	            return;
369	        }
370	        String trimmed = email.strip();
371	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
372	            throw new InvalidEmailException(email);
373	        }
374	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
375	    }
376	
377	    /**
378	     * Defaults the registration date on create: when the client does not supply a
379	     * {@code registrationDate}, it is set to the server's current date so it is persisted
380	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
381	     *
382	     * @param ownerFieldsDto the submitted owner fields
383	     */
384	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
385	        if (ownerFieldsDto.getRegistrationDate() == null) {
386	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
387	        }
388	    }
389	
390	    /**
391	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<LAST3>-<NNNN>'}
392	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
393	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
394	     * (e.g. {@code 'SMI-0007'}).
395	     *
396	     * @param owner the owner being created (with its {@code lastName} already set)
397	     */
398	    private void assignCustomerCode(Owner owner) {
399	        String lastName = owner.getLastName();
400	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
401	        int sequence = this.clinicService.findAllOwners().size() + 1;
402	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
403	    }
404	
405	    /**
406	     * Assigns the owner's {@code householdId} on create: a stable identifier for the household,
407	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
408	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
409	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
410	     * canonicalized fields, every owner in the same household — including one joining an existing
411	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
412	     * order.
413	     *
414	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
415	     */
416	    private void assignHouseholdId(Owner owner) {
417	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
418	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
419	    }
420	
421	    /**
422	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
423	     * already share this owner's {@code firstName} and {@code lastName}, compared
424	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
425	     * pre-existing namesakes.
426	     *
427	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
428	     */
429	    private void assignNamesakeCount(Owner owner) {
430	        String firstName = owner.getFirstName();
431	        String lastName = owner.getLastName();
432	        long count = this.clinicService.findAllOwners().stream()
433	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
434	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
435	            .count();
436	        owner.setNamesakeCount((int) count);
437	    }
438	
439	    /**
440	     * Assigns the owner's {@code membershipNumber} on create, formatted
441	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
442	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
443	     * (e.g. {@code 'SMI-0007-M26'}). Derived purely from the owner's own fields, so both
444	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
445	     *
446	     * @param owner the owner being created (with its {@code customerCode} and
447	     *              {@code registrationDate} already set)
448	     */
449	    private void assignMembershipNumber(Owner owner) {
450	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
451	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
452	    }
453	
454	    /**
455	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
456	     *
457	     * @param value the string to hash
458	     * @return the 64-character lower-case hex digest
459	     */
460	    private static String sha256Hex(String value) {
461	        try {
462	            byte[] digest = MessageDigest.getInstance("SHA-256")
463	                .digest(value.getBytes(StandardCharsets.UTF_8));
464	            StringBuilder sb = new StringBuilder(digest.length * 2);
465	            for (byte b : digest) {
466	                sb.append(String.format("%02x", b));
467	            }
468	            return sb.toString();
469	        }
470	        catch (NoSuchAlgorithmException e) {
471	            throw new IllegalStateException("SHA-256 not available", e);
472	        }
473	    }
474	
475	    private void rejectDuplicateTelephone(String normalizedTelephone) {
476	        boolean duplicate = this.clinicService.findAllOwners().stream()
477	            .map(Owner::getTelephone)
478	            .map(OwnerRestControllerV1::toE164)
479	            .filter(telephone -> telephone != null)
480	            .anyMatch(normalizedTelephone::equals);
481	        if (duplicate) {
482	            throw new DuplicateTelephoneException(normalizedTelephone);
483	        }
484	    }
485	
486	    /**
487	     * Rejects a create whose {@code lastName} and {@code address} match those of an existing
488	     * owner. Both fields are compared with {@link #collapse} — trimmed, internal whitespace
489	     * runs collapsed to a single space, and case-insensitive — so differing spacing or casing
490	     * still counts as the same household. The check is skipped when the request opts in via
491	     * {@code sharesHousehold == true}, acknowledging that the new owner shares a household with
492	     * the existing one.
493	     *
494	     * @param ownerFieldsDto the submitted owner fields
495	     * @throws DuplicateHouseholdException with a 409 status if another owner already has the same
496	     *                                     last name and address and the request did not opt in
497	     */
498	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
499	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
500	            return;
501	        }
502	        String lastName = collapse(ownerFieldsDto.getLastName());
503	        String address = collapse(ownerFieldsDto.getAddress());
504	        boolean duplicate = this.clinicService.findAllOwners().stream()
505	            .anyMatch(owner -> collapse(owner.getLastName()).equals(lastName)
506	                && collapse(owner.getAddress()).equals(address));
507	        if (duplicate) {
508	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
509	        }
510	    }
511	
512	    /**
513	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
514	     * every internal run of whitespace is collapsed to a single space, and the result is
515	     * lower-cased. A {@code null} value collapses to the empty string.
516	     *
517	     * @param value the value to canonicalize, possibly {@code null}
518	     * @return the collapsed, lower-cased value
519	     */
520	    private static String collapse(String value) {
521	        if (value == null) {
522	            return "";
523	        }
524	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
525	    }
526	
527	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
528	    @Override
529	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
530	        Owner owner = this.clinicService.findOwnerById(ownerId);
531	        if (owner != null) {
532	            Pet pet = owner.getPet(petId);
533	            if (pet != null) {
534	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
535	            }
536	        }
537	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
538	    }
539	}
